    `Search path/config: \`${JSON.stringify(row.configuration)}\`.`,
    `Effective EXECUTE grants: \`${JSON.stringify(row.executeGrants)}\`.`,
    `Raw ACL: \`${JSON.stringify(row.acl)}\`; extension: \`${row.extension ?? 'none'}\`.`, '',
