    } catch (recoveryError) {
      notify(businessErrorMessage(recoveryError), 'error');
    } finally {
      try { await refreshRecoveryStates(); } catch { /* load exposes recovery read errors */ }
      setBusy(false);
    }
  };

  return (
    <FormFields><section data-testid="phase43-admin-aftercare" aria-busy={busy}
