          </p>
        </div>
        <span className={`rounded-full px-2 py-1 text-[9px] font-bold ${context.order.withinWindow
          ? 'bg-nw-ok-bg text-nw-text' : 'bg-nw-bad-bg text-nw-text'}`}>
          {context.order.withinWindow ? 'ضمن 48 ساعة' : 'انتهت المهلة'}
