import React, { useCallback, useState, useSyncExternalStore } from 'react';
import {
  AlertTriangle,
  Banknote,
  BookUser,
  CheckCircle2,
  ChevronLeft,
  ChevronRight,
  Clock3,
  Copy,
  MessageCircle,
  PackageCheck,
  Phone,
  Printer,
  ReceiptText,
  Share2,
  RotateCcw,
  Smartphone,
  Truck,
  X,
  XCircle,
} from 'lucide-react';
import { MoneyText, StatusBadge, UiButton, formatUiDate } from '../../components/ui';
import { getOrderStatus, PAYMENT_METHOD_LABELS } from './orderStatus';
import { OrderCommercialSummary } from './OrderCommercialSummary';
import { useDialogFocus } from '../../hooks/useDialogFocus';
import { CURRENCY } from '../../constants';
import { useAppStoreActions, useAppStoreSelector } from '../../stores/useAppStore';
import { Order, OrderStatus } from '../../types';
import { CustomerLocationCard } from './CustomerLocationCard';
import { EditAddressModal } from './EditAddressModal';
import { AdminAftercarePanel } from './AdminAftercarePanel';
import { buildStorefrontTrackingUrl } from '../../services/supabase/orders.service';
import type { AdminAftercareCapability } from '../../services/supabase/salesAftercare.service';
import {DocumentCorrectionAction} from '../corrections/DocumentCorrectionAction';
import {SaleReceiptDialog} from '../receipts/SaleReceiptDialog';
import {orderReceipt} from '../receipts/saleReceipt';
import {receiptDocumentShareText} from '../../../customer-web/src/receipts/commercialReceipt';

interface OrderDetailModalProps {
  order: Order;
  onClose: () => void;
  onOrderChanged?: () => Promise<void>;
  embedded?: boolean;
  historyContext?: boolean;
  onPrint?: () => void;
}

const STATUS_LABELS: Record<string, string> = {
  new: 'طلب جديد',
  confirmed: 'مؤكد',
  preparing: 'قيد التجهيز',
  processing: 'قيد التجهيز',
  ready: 'جاهز للتوصيل',
  out_for_delivery: 'خرج للتوصيل',
  delivered: 'مكتمل',
  completed: 'مكتمل',
  cancelled: 'ملغي',
  returned: 'مرتجع',
  expired: 'انتهت مهلة الحجز',
};



function nextOrderStep(status: OrderStatus) {
  if (status === 'confirmed') {
    return {
      status: 'preparing' as OrderStatus,
      label: 'بدء تجهيز الطلب',
      icon: PackageCheck,
      color: 'bg-nw-primary hover:bg-nw-primary',
    };
  }
  if (status === 'preparing' || status === 'processing') {
    return {
      status: 'out_for_delivery' as OrderStatus,
      label: 'بدء التوصيل',
      icon: Truck,
      color: 'bg-nw-primary hover:bg-nw-primary',
    };
  }
  if (status === 'ready') {
    return {
      status: 'out_for_delivery' as OrderStatus,
      label: 'خرج الطلب للتوصيل',
      icon: Truck,
      color: 'bg-nw-primary hover:bg-nw-primary',
    };
  }
  if (status === 'out_for_delivery') {
    return {
      status: 'delivered' as OrderStatus,
      label: 'تأكيد التسليم وخصم المخزون',
      icon: CheckCircle2,
      color: 'bg-nw-primary hover:bg-nw-primary',
    };
  }
  return null;
}

function normalizeJordanianPhone(value: string): string | null {
  const digits = value.replace(/\D/g, '');
  const local = digits.startsWith('962')
    ? `0${digits.slice(3)}`
    : digits.startsWith('0')
      ? digits
      : `0${digits}`;
  return /^07[789]\d{7}$/.test(local) ? local : null;
}

const subscribePhoneViewport = (notify: () => void) => {
  const query = window.matchMedia('(max-width: 767px)');
  query.addEventListener('change', notify);
  return () => query.removeEventListener('change', notify);
};
const isPhoneViewport = () => window.matchMedia('(max-width: 767px)').matches;

export const OrderDetailModal: React.FC<OrderDetailModalProps> = ({
  order,
  onClose,
  onOrderChanged,
  embedded = false,
  historyContext = false,
  onPrint,
}) => {
  const {
    confirmOrder,
    cancelOrder,
    advanceOrderStatus,
    startOrUpdateOrderDelivery,
    completeWebsiteOrderWithSettlement,
    openCustomerProfile,
    setToast,
  } = useAppStoreActions();

  const [busy, setBusy] = useState(false);
  const [showReceipt, setShowReceipt] = useState(false);
  const receiptBranch = useAppStoreSelector(state => state.branches.find(branch => branch.id === order.branchId));
  const savedReceipt = orderReceipt(order, receiptBranch);
  const copyReceiptLink = async () => {
    if (!order.publicReceiptUrl) return;
    try {
      await navigator.clipboard.writeText(order.publicReceiptUrl);
      setToast('تم نسخ رابط الوصل.', 'success');
    } catch {
      setToast('تعذر نسخ رابط الوصل على هذا الجهاز.', 'error');
    }
  };
  const shareReceipt = async () => {
    if (!order.publicReceiptUrl) return;
    try {
      const text = receiptDocumentShareText(savedReceipt, order.publicReceiptUrl);
      if (navigator.share) await navigator.share({title:`وصل ${order.orderNumber}`, text, url:order.publicReceiptUrl});
      else {
        await navigator.clipboard.writeText(text);
        setToast('تم نسخ الوصل مع رابطه للمشاركة.', 'success');
      }
    } catch (error) {
      if (error instanceof DOMException && error.name === 'AbortError') return;
      setToast('تعذرت مشاركة الوصل على هذا الجهاز.', 'error');
    }
  };
  const [showCancelForm, setShowCancelForm] = useState(false);
