const fingerprintRequest = (request: Record<string, unknown>) => sha256(canonicalString(request));
const buildKey = async (
  actorId: string,
  orderId: string,
  action: string,
  intentId: string,
  attemptId: string,
) => `phase43:${await sha256(
  `phase43-aftercare:${actorId}:${orderId}:${action}:${intentId}:${attemptId}`,
)}`;
