    let previousObservation: AftercareAttempt | null | undefined;
    // A granted Web Lock does not flush WebKit's localStorage snapshot. Re-read
    // at most twice on a pre-write CAS change, never retry the business RPC.
    for (let decision = 0; decision < 3; decision += 1) {
      const raw = localStorage.getItem(storageKey);
      let existing: AftercareAttempt | null = null;

      if (intent === 'RECOVER_EXISTING') {
        if (raw === null) {
          throw new Error('AFTERCARE_RECOVERY_NOT_FOUND: لا توجد محاولة معلقة للتعافي.');
        }
        attempt = await validateAttempt(JSON.parse(raw), actorId, orderId, action);
        existing = attempt;
        if (previousObservation !== undefined && (previousObservation === null
          || !sameAttemptIdentity(existing, previousObservation))) throw reviewRequired();
        if (capturedRequest !== null && !sameRequest(attempt.request, capturedRequest)) {
          throw reviewRequired();
        }
        if (!['IN_FLIGHT', 'OUTCOME_UNKNOWN'].includes(attempt.status)) {
          if (attempt.status === 'SUCCEEDED') return {data: attempt.result!, error: null};
          throw new Error('AFTERCARE_RECOVERY_NOT_AVAILABLE: المحاولة الحالية ليست معلقة.');
        }
      } else {
        if (!isObject(capturedRequest)) throw reviewRequired();
        if (raw !== null) {
          const previous = await validateAttempt(JSON.parse(raw), actorId, orderId, action);
          existing = previous;
          if (['IN_FLIGHT', 'OUTCOME_UNKNOWN'].includes(previous.status)) {
            throw new Error('AFTERCARE_OUTCOME_UNKNOWN: عالج المحاولة السابقة قبل بدء إجراء جديد.');
          }
        }
        if (previousObservation !== undefined && (existing === null
          ? previousObservation !== null
          : previousObservation === null || !sameAttemptIdentity(existing, previousObservation))) {
          throw reviewRequired();
        }
        const request = capturedRequest;
        const intentId = nextIdentity();
        const attemptId = nextIdentity();
        attempt = {
          version: 2, actorId, orderId, action, intentId, attemptId,
          idempotencyKey: await buildKey(actorId, orderId, action, intentId, attemptId),
          requestFingerprint: await fingerprintRequest(request), request,
          status: 'PREPARED', generation: 0, hadUnknownOutcome: false,
        };
      }

      if (localStorage.getItem(storageKey) !== raw) {
        if (decision === 2) throw reviewRequired();
        previousObservation = existing;
        continue;
      }
      attempt = {...attempt, status: 'IN_FLIGHT', generation: attempt.generation + 1,
        hadUnknownOutcome: attempt.hadUnknownOutcome
          || attempt.status === 'IN_FLIGHT' || attempt.status === 'OUTCOME_UNKNOWN'};
      save(storageKey, attempt);
      break;
    }
    const sentAttempt = structuredClone(attempt);

    let response: {data: unknown; error: any};
    try {
      response = await invoke(attempt.idempotencyKey, structuredClone(attempt.request));
    } catch (error) {
      const fresh = await validateAttempt(JSON.parse(localStorage.getItem(storageKey) || 'null'),
        actorId, orderId, action);
      if (completedSameAttempt(fresh, sentAttempt)) return {data: fresh.result!, error: null};
      if (!sameAttemptIdentity(fresh, sentAttempt)) throw reviewRequired();
      if (fresh.status !== 'IN_FLIGHT') throw reviewRequired();
      save(storageKey, {...fresh, status: 'OUTCOME_UNKNOWN', hadUnknownOutcome: true});
      throw error;
    }

    const fresh = await validateAttempt(JSON.parse(localStorage.getItem(storageKey) || 'null'),
      actorId, orderId, action);
    if (completedSameAttempt(fresh, sentAttempt)) return {data: fresh.result!, error: null};
    if (!sameAttemptIdentity(fresh, sentAttempt)) throw reviewRequired();
    if (fresh.status !== 'IN_FLIGHT') throw reviewRequired();
    if (!response.error && successMatches(action, orderId, fresh.request, response.data)) {
      const result = structuredClone(response.data);
      save(storageKey, {...fresh, status: 'SUCCEEDED', result});
      return {data: result, error: null};
    }
    if (response.error) {
      const canReject = !fresh.hadUnknownOutcome && response.data === null
        && isDefinitiveRejection(action, response.error, response.data);
      save(storageKey, {...fresh,
        status: canReject ? 'DEFINITIVELY_REJECTED' : 'OUTCOME_UNKNOWN',
        hadUnknownOutcome: fresh.hadUnknownOutcome || !canReject});
      return {data: null, error: response.error};
    }
    save(storageKey, {...fresh, status: 'OUTCOME_UNKNOWN', hadUnknownOutcome: true});
    return {data: null, error: {message:
      'AFTERCARE_RESPONSE_INVALID: وصل رد غير مكتمل؛ أعد نفس المحاولة للتعافي.'}};
  });
}

src/services/supabase/expenses-shifts.se.beforeText:
import { isSupabaseConfigured, supabase } from '../../lib/supabase';
import type { Expense, Shift, ShiftClosingReport } from '../../types';

type RpcRecord = Record<string, unknown>;

export interface ExpenseShiftCenter {
  expenses: Expense[];
  currentShift: Shift | null;
  recentShifts: Shift[];
}

export interface CashShiftArchiveFilters {
  branchId?: string;
  cashierId?: string;
  status?: Shift['status'];
  shiftNumber?: string;
  dateFrom?: string;
  dateTo?: string;
  limit: number;
  offset: number;
}

export interface CashShiftArchivePage {
  shifts: Shift[];
  totalCount: number;
  limit: number;
  offset: number;
  hasMore: boolean;
  cashiers: Array<{ id: string; name: string }>;
}

export interface OperationalExpenseInput {
  branchId: string;
  category: string;
  description: string;
  amount: number;
  paymentMethod: 'cash' | 'cliq';
  referenceNumber?: string;
}

export type CashShiftFullReversalOperationStatus =
  | 'SUPPORTED'
  | 'BLOCKED'
  | 'ALREADY_REVERSED'
  | 'UNSUPPORTED';

export interface CashShiftFullReversalOperation {
  operationType: string;
  originalRecordId: string;
  status: CashShiftFullReversalOperationStatus;
  reason?: string;
  expectedEffect: Record<string, number>;
}

export interface CashShiftFullReversalPreview {
  shiftId: string;
  shiftNumber: string;
  shiftStatus: string;
  canExecute: boolean;
  operations: CashShiftFullReversalOperation[];
  summary: Record<string, number>;
  scopeNote?: string;
  /** Owner withdrawals handled by the same atomic reversal (migration 180). */
  ownerWithdrawals?: {
    canExecute: boolean;
    blockedReason?: string;
    withdrawalsToReverseCount: number;
    returnsToVoidCount: number;
    cashBackToDrawer: number;
    cashOutAgain: number;
  };
}

export interface CashShiftFullReversalResult {
  reversalId: string;
  idempotent: boolean;
  actualEffect: Record<string, number>;
  operations: CashShiftFullReversalOperation[];
  message: string;
}

const textValue = (value: unknown): string =>
  typeof value === 'string' ? value : '';

const minorUnitsToJod = (value: unknown): number => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed / 1000 : 0;
};

const jodToMinorUnits = (value: number): number =>
  Math.round(Math.max(0, value) * 1000);

function requireClient() {
  if (!isSupabaseConfigured || !supabase) {
    throw new Error('إعدادات الاتصال بـ Supabase غير مكتملة.');
  }
  return supabase;
}

function mapShift(payload: RpcRecord): Shift {
  const cashReceipts = minorUnitsToJod(payload.cashReceiptsInMinorUnits);
  const cliqReceipts = minorUnitsToJod(payload.cliqReceiptsInMinorUnits);
  const cashSupplierPayments = minorUnitsToJod(
    payload.cashSupplierPaymentsInMinorUnits
  );
  const cliqSupplierPayments = minorUnitsToJod(
    payload.cliqSupplierPaymentsInMinorUnits
  );
  const cashExpenses = minorUnitsToJod(payload.cashExpensesInMinorUnits);
  const cliqExpenses = minorUnitsToJod(payload.cliqExpensesInMinorUnits);
  const cashRefunds = minorUnitsToJod(payload.cashRefundsInMinorUnits);
  const cliqRefunds = minorUnitsToJod(payload.cliqRefundsInMinorUnits);

  return {
    id: textValue(payload.id),
    shiftNumber: textValue(payload.shiftNumber),
    branchId: textValue(payload.branchId),
    cashierName: textValue(payload.cashierName) || 'مستخدم النظام',
    startTime: textValue(payload.startTime),
    endTime: textValue(payload.endTime) || undefined,
    openingCash: minorUnitsToJod(payload.openingCashInMinorUnits),
    totalCashSales: minorUnitsToJod(payload.cashSalesInMinorUnits),
    totalCliqSales: minorUnitsToJod(payload.cliqSalesInMinorUnits),
    totalCardSales: minorUnitsToJod(payload.cardSalesInMinorUnits),
    totalReceipts: cashReceipts + cliqReceipts,
    totalPayments:
      cashSupplierPayments +
      cliqSupplierPayments +
      cashExpenses +
      cliqExpenses +
      cashRefunds +
      cliqRefunds,
    cashReceipts,
    cliqReceipts,
    cashSupplierPayments,
    cliqSupplierPayments,
    cashExpenses,
    cliqExpenses,
    cashRefunds,
    cliqRefunds,
    ownerWithdrawals: minorUnitsToJod(payload.ownerWithdrawalsInMinorUnits),
    ownerWithdrawalReturns: minorUnitsToJod(payload.ownerWithdrawalReturnsInMinorUnits),
    expectedCash: minorUnitsToJod(payload.expectedCashInMinorUnits),
    actualCash:
      payload.actualCashInMinorUnits === null ||
      payload.actualCashInMinorUnits === undefined
        ? undefined
        : minorUnitsToJod(payload.actualCashInMinorUnits),
    cashDiscrepancy:
      payload.cashDiscrepancyInMinorUnits === null ||
      payload.cashDiscrepancyInMinorUnits === undefined
        ? undefined
        : minorUnitsToJod(payload.cashDiscrepancyInMinorUnits),
    discrepancyReason: textValue(payload.discrepancyReason) || undefined,
    status:
      payload.status === 'cancelled'
        ? 'cancelled'
        : payload.status === 'reversed'
          ? 'reversed'
          : payload.status === 'closed'
            ? 'closed'
            : 'open',
    managerSignOffBy: textValue(payload.managerSignOffBy) || undefined,
    cancelledByName: textValue(payload.cancelledByName) || undefined,
    cancelledAt: textValue(payload.cancelledAt) || undefined,
    cancellationReason: textValue(payload.cancellationReason) || undefined,
    reversedByName: textValue(payload.reversedByName) || undefined,
    reversedAt: textValue(payload.reversedAt) || undefined,
    reversalReason: textValue(payload.reversalReason) || undefined,
    reversalId: textValue(payload.reversalId) || undefined,
  };
}

const numericEffect = (value: unknown): Record<string, number> => {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
  return Object.fromEntries(
    Object.entries(value as RpcRecord).flatMap(([key, entry]) => {
      const parsed = Number(entry);
      return Number.isFinite(parsed) ? [[key, parsed]] : [];
    })
  );
};

const mapFullShiftReversalOperation = (
  value: unknown
): CashShiftFullReversalOperation => {
  const payload = (value && typeof value === 'object' ? value : {}) as RpcRecord;
  const status = textValue(payload.status);
  return {
    operationType: textValue(payload.operationType),
    originalRecordId: textValue(payload.originalRecordId),
    status:
      status === 'SUPPORTED' ||
      status === 'BLOCKED' ||
      status === 'ALREADY_REVERSED' ||
      status === 'UNSUPPORTED'
        ? status
        : 'UNSUPPORTED',
    reason: textValue(payload.reason) || undefined,
    expectedEffect: numericEffect(payload.expectedEffect),
  };
};

export async function previewCashShiftFullReversalFromSupabase(
  shiftId: string
): Promise<CashShiftFullReversalPreview> {
  const { data, error } = await requireClient().rpc(
    'preview_cash_shift_full_reversal',
    { p_shift_id: shiftId }
  );
  if (error) throw new Error(error.message || 'تعذر معاينة عكس الوردية.');
  const payload = (data || {}) as RpcRecord;
  if (payload.success !== true) {
    throw new Error(textValue(payload.message) || 'تعذر معاينة عكس الوردية.');
  }
  return {
    shiftId: textValue(payload.shiftId),
    shiftNumber: textValue(payload.shiftNumber),
    shiftStatus: textValue(payload.shiftStatus),
    canExecute: payload.canExecute === true,
    operations: Array.isArray(payload.operations)
      ? payload.operations.map(mapFullShiftReversalOperation)
      : [],
    summary: numericEffect(payload.summary),
    scopeNote: textValue(payload.scopeNote) || undefined,
    ownerWithdrawals: mapOwnerWithdrawalReversalPlan(payload.ownerWithdrawals),
  };
}

function mapOwnerWithdrawalReversalPlan(value: unknown): CashShiftFullReversalPreview['ownerWithdrawals'] {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return undefined;
  const plan = value as RpcRecord;
  const reverse = Array.isArray(plan.withdrawalsToReverse) ? plan.withdrawalsToReverse.length : 0;
  const voids = Array.isArray(plan.returnsToVoid) ? plan.returnsToVoid.length : 0;
  const blockedReason = textValue(plan.blockedReason).replace(/^[A-Z0-9_]+:\s*/u, '');
  if (plan.canExecute === true && reverse === 0 && voids === 0) return undefined;
  return {
    canExecute: plan.canExecute === true,
    blockedReason: blockedReason || undefined,
    withdrawalsToReverseCount: reverse,
    returnsToVoidCount: voids,
    cashBackToDrawer: minorUnitsToJod(plan.cashBackToDrawerInMinorUnits),
    cashOutAgain: minorUnitsToJod(plan.cashOutAgainInMinorUnits),
  };
}

function mapClosingOwnerWithdrawals(value: unknown): ShiftClosingReport['ownerWithdrawals'] {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return undefined;
  const section = value as RpcRecord;
  const items = Array.isArray(section.items) ? section.items : [];
  return {
    net: minorUnitsToJod(section.netInMinorUnits),
    netMovementAfterWithdrawals: section.netMovementAfterWithdrawalsInMinorUnits == null
      ? undefined : minorUnitsToJod(section.netMovementAfterWithdrawalsInMinorUnits),
    withdrawn: minorUnitsToJod(section.withdrawnInMinorUnits),
    returned: minorUnitsToJod(section.returnedInMinorUnits),
    items: items.map((item) => {
      const record = item as RpcRecord;
      return {
        kind: record.kind === 'return' ? 'return' : 'withdrawal',
        withdrawalNumber: textValue(record.withdrawalNumber),
        amount: minorUnitsToJod(record.amountInMinorUnits),
        at: textValue(record.at),
        originalShiftNumber: textValue(record.originalShiftNumber) || undefined,
      };
    }),
  };
}

export async function reverseCashShiftWithOperationsInSupabase(
  shiftId: string,
  reason: string,
  idempotencyKey: string
): Promise<CashShiftFullReversalResult> {
  const { data, error } = await requireClient().rpc(
    'reverse_cash_shift_with_operations',
    {
      p_shift_id: shiftId,
      p_reason: reason.trim(),
      p_idempotency_key: idempotencyKey,
    }
  );
  if (error) throw new Error(error.message || 'تعذر عكس عمليات الوردية.');
  const payload = (data || {}) as RpcRecord;
  if (payload.success !== true) {
    throw new Error(textValue(payload.message) || 'تعذر عكس عمليات الوردية.');
  }
  return {
    reversalId: textValue(payload.reversalId),
    idempotent: payload.idempotent === true,
    actualEffect: numericEffect(payload.actualEffect),
    operations: Array.isArray(payload.operations)
      ? payload.operations.map(mapFullShiftReversalOperation)
      : [],
    message:
      textValue(payload.message) ||
      'تم عكس عمليات الوردية وحفظ سجل المراجعة.',
  };
}

export async function fetchCashShiftClosingReportFromSupabase(
  shiftId: string
): Promise<ShiftClosingReport> {
  const { data, error } = await requireClient().rpc(
    'get_cash_shift_closing_report',
    { p_shift_id: shiftId }
  );
  if (error) {
    throw new Error(error.message || 'تعذر تحميل تقرير إغلاق الوردية.');
  }

  const payload = (data || {}) as RpcRecord;
  if (payload.success !== true) {
    throw new Error(
      textValue(payload.message) || 'تعذر تحميل تقرير إغلاق الوردية.'
    );
  }

  const sales = (payload.sales || {}) as RpcRecord;
  const collections = (payload.collections || {}) as RpcRecord;
  const outflows = (payload.outflows || {}) as RpcRecord;
  const reconciliation = (payload.reconciliation || {}) as RpcRecord;

  return {
    generatedAt: textValue(payload.generatedAt),
    ...(payload.salesDetailStatus === 'available' || payload.salesDetailStatus === 'unavailable'
      ? {salesDetailStatus: payload.salesDetailStatus} : {}),
    snapshotStatus:
      payload.snapshotStatus === 'immutable' ||
      payload.snapshotStatus === 'legacy_recalculated' ||
      payload.snapshotStatus === 'live' ||
      payload.snapshotStatus === 'not_applicable'
        ? payload.snapshotStatus
        : undefined,
    shift: mapShift((payload.shift || {}) as RpcRecord),
    sales: {
      orderCount: Number(sales.orderCount) || 0,
      posOrderCount: Number(sales.posOrderCount) || 0,
      websiteOrderCount: Number(sales.websiteOrderCount) || 0,
      packageCount: Number(sales.packageCount) || 0,
      uniqueProductCount: Number(sales.uniqueProductCount) || 0,
      grossSales: minorUnitsToJod(sales.grossSalesInMinorUnits),
      refunds: minorUnitsToJod(sales.refundsInMinorUnits),
      netSales: minorUnitsToJod(sales.netSalesInMinorUnits),
      ...(sales.salesDefinitionVersion === 133 ? {
        salesDefinitionVersion: 133 as const,
        collectedDirectSales: minorUnitsToJod(sales.collectedDirectSalesInMinorUnits),
        initialReceiptPayments: minorUnitsToJod(sales.initialReceiptPaymentsInMinorUnits),
        initialReceiptCash: minorUnitsToJod(sales.initialReceiptCashInMinorUnits),
        initialReceiptCliq: minorUnitsToJod(sales.initialReceiptCliqInMinorUnits),
        creditSales: minorUnitsToJod(sales.creditSalesInMinorUnits),
        returnEntitlement: minorUnitsToJod(sales.returnEntitlementInMinorUnits),
        debtReduction: minorUnitsToJod(sales.debtReductionInMinorUnits),
      } : {}),
    },
    collections: {
      count: Number(collections.count) || 0,
      cash: minorUnitsToJod(collections.cashInMinorUnits),
      cliq: minorUnitsToJod(collections.cliqInMinorUnits),
      ...(sales.salesDefinitionVersion === 133 ? {
        initialPayments: minorUnitsToJod(collections.initialPaymentsInMinorUnits),
        initialCash: minorUnitsToJod(collections.initialCashInMinorUnits),
        initialCliq: minorUnitsToJod(collections.initialCliqInMinorUnits),
      } : {}),
    },
    outflows: {
      supplierPaymentCount: Number(outflows.supplierPaymentCount) || 0,
      cashSupplierPayments: minorUnitsToJod(
        outflows.cashSupplierPaymentsInMinorUnits
      ),
      cliqSupplierPayments: minorUnitsToJod(
        outflows.cliqSupplierPaymentsInMinorUnits
      ),
      expenseCount: Number(outflows.expenseCount) || 0,
      cashExpenses: minorUnitsToJod(outflows.cashExpensesInMinorUnits),
      cliqExpenses: minorUnitsToJod(outflows.cliqExpensesInMinorUnits),
      returnCount: Number(outflows.returnCount) || 0,
      cashRefunds: minorUnitsToJod(outflows.cashRefundsInMinorUnits),
      cliqRefunds: minorUnitsToJod(outflows.cliqRefundsInMinorUnits),
    },
    reconciliation: {
      totalInflows: minorUnitsToJod(
        reconciliation.totalInflowsInMinorUnits
      ),
      totalOutflows: minorUnitsToJod(
        reconciliation.totalOutflowsInMinorUnits
      ),
      netMovement: minorUnitsToJod(
        reconciliation.netMovementInMinorUnits
      ),
      netCliqMovement: minorUnitsToJod(
        reconciliation.netCliqMovementInMinorUnits
      ),
      openingCash: minorUnitsToJod(
        reconciliation.openingCashInMinorUnits
      ),
      expectedCash: minorUnitsToJod(
        reconciliation.expectedCashInMinorUnits
      ),
      actualCash:
        reconciliation.actualCashInMinorUnits === null ||
        reconciliation.actualCashInMinorUnits === undefined
          ? undefined
          : minorUnitsToJod(reconciliation.actualCashInMinorUnits),
      cashDiscrepancy:
        reconciliation.cashDiscrepancyInMinorUnits === null ||
        reconciliation.cashDiscrepancyInMinorUnits === undefined
          ? undefined
          : minorUnitsToJod(
              reconciliation.cashDiscrepancyInMinorUnits
            ),
      isBalanced:
        typeof reconciliation.isBalanced === 'boolean'
          ? reconciliation.isBalanced
          : undefined,
    },
    expenseBreakdown: Array.isArray(payload.expenseBreakdown)
      ? payload.expenseBreakdown.map((item) => {
          const record = item as RpcRecord;
          return {
            category: textValue(record.category),
            count: Number(record.count) || 0,
            amount: minorUnitsToJod(record.amountInMinorUnits),
          };
        })
      : [],
    ownerWithdrawals: mapClosingOwnerWithdrawals(payload.ownerWithdrawals),
    returnQuantityBreakdown: Array.isArray(payload.returnQuantityBreakdown)
      ? payload.returnQuantityBreakdown.map((item) => {
          const record = item as RpcRecord;
          return {eventId: textValue(record.eventId), productId: textValue(record.productId),
            productName: textValue(record.productName), sellableQuantity: Number(record.sellableQuantity),
            defectQuantity: Number(record.defectQuantity), customerDamageQuantity: Number(record.customerDamageQuantity)};
        })
      : undefined,
    returnBreakdown: Array.isArray(payload.returnBreakdown)
      ? payload.returnBreakdown.map((item) => {
          const record = item as RpcRecord;
          return {
            refundMethod: record.refundMethod === 'cliq' ? 'cliq' : 'cash',
            stockDisposition:
              record.stockDisposition === 'damaged' ? 'damaged' : 'restock',
            count: Number(record.count) || 0,
            amount: minorUnitsToJod(record.amountInMinorUnits),
          };
        })
      : [],
  };
}

function mapExpense(payload: RpcRecord): Expense {
  return {
    id: textValue(payload.id),
    expenseNumber: textValue(payload.expenseNumber),
    shiftId: textValue(payload.shiftId),
    category: textValue(payload.category),
    amount: minorUnitsToJod(payload.amountInMinorUnits),
    paymentMethod: payload.paymentMethod === 'cliq' ? 'cliq' : 'cash',
    referenceNumber: textValue(payload.referenceNumber) || undefined,
    description: textValue(payload.description),
    isApproved: true,
    approvedBy: textValue(payload.createdByName) || undefined,
    branchId: textValue(payload.branchId),
    createdByName: textValue(payload.createdByName) || 'مستخدم النظام',
    createdAt: textValue(payload.createdAt),
    isReversed: payload.isReversed === true,
    reversedAt: textValue(payload.reversedAt) || undefined,
    reversalReason: textValue(payload.reversalReason) || undefined,
    reversedByName: textValue(payload.reversedByName) || undefined,
  };
}

export async function fetchExpenseShiftCenterFromSupabase(
  branchId: string
): Promise<ExpenseShiftCenter> {
  const { data, error } = await requireClient().rpc(
    'get_expense_shift_center',
    { p_branch_id: branchId, p_expense_limit: 100 }
  );
  if (error) throw new Error(error.message || 'تعذر تحميل مركز الصندوق.');

  const payload = (data || {}) as RpcRecord;
  if (payload.success !== true) {
    throw new Error(textValue(payload.message) || 'تعذر تحميل مركز الصندوق.');
  }

  return {
    expenses: Array.isArray(payload.expenses)
      ? payload.expenses.map((item) => mapExpense(item as RpcRecord))
      : [],
    currentShift:
      payload.currentShift && typeof payload.currentShift === 'object'
        ? mapShift(payload.currentShift as RpcRecord)
        : null,
    recentShifts: Array.isArray(payload.recentShifts)
      ? payload.recentShifts.map((item) => mapShift(item as RpcRecord))
      : [],
  };
}

export async function fetchCashShiftArchivePageFromSupabase(
  input: CashShiftArchiveFilters
): Promise<CashShiftArchivePage> {
  const { data, error } = await requireClient().rpc('get_cash_shift_archive_page', {
    p_branch_id: input.branchId || null,
    p_cashier_id: input.cashierId || null,
    p_status: input.status || null,
    p_shift_number: input.shiftNumber?.trim() || null,
    p_date_from: input.dateFrom || null,
    p_date_to: input.dateTo || null,
    p_limit: input.limit,
    p_offset: input.offset,
  });
  if (error) throw new Error(error.message || 'تعذر تحميل أرشيف الورديات.');

  const payload = (data || {}) as RpcRecord;
  if (payload.success !== true) {
    throw new Error(textValue(payload.message) || 'تعذر تحميل أرشيف الورديات.');
  }

  return {
    shifts: Array.isArray(payload.items)
      ? payload.items.map((item) => mapShift(item as RpcRecord))
      : [],
    totalCount: Math.max(0, Number(payload.totalCount) || 0),
    limit: Math.max(1, Number(payload.limit) || input.limit),
    offset: Math.max(0, Number(payload.offset) || 0),
    hasMore: payload.hasMore === true,
    cashiers: Array.isArray(payload.cashiers)
      ? payload.cashiers.flatMap((item) => {
          const record = item as RpcRecord;
          const id = textValue(record.id);
          return id ? [{ id, name: textValue(record.name) || 'مستخدم النظام' }] : [];
        })
      : [],
  };
}

export async function openCashShiftInSupabase(
  branchId: string,
  openingCash: number
): Promise<{ shift: Shift; message: string }> {
  const { data, error } = await requireClient().rpc('open_cash_shift', {
    p_branch_id: branchId,
    p_opening_cash_in_minor_units: jodToMinorUnits(openingCash),
  });
  if (error) throw new Error(error.message || 'تعذر فتح الوردية.');
  const payload = (data || {}) as RpcRecord;
  if (payload.success !== true) {
    throw new Error(textValue(payload.message) || 'تعذر فتح الوردية.');
  }
  return {
    shift: mapShift(payload),
    message: textValue(payload.message) || 'تم فتح الوردية.',
  };
}

export async function createOperationalExpenseInSupabase(
  input: OperationalExpenseInput
): Promise<{ message: string }> {
  const { data, error } = await requireClient().rpc(
    'create_operational_expense',
    {
      p_branch_id: input.branchId,
      p_category: input.category.trim(),
      p_description: input.description.trim(),
      p_amount_in_minor_units: jodToMinorUnits(input.amount),
      p_payment_method: input.paymentMethod,
      p_reference_number: input.referenceNumber?.trim() || null,
    }
  );
  if (error) throw new Error(error.message || 'تعذر تسجيل المصروف.');
  const payload = (data || {}) as RpcRecord;
  if (payload.success !== true) {
    throw new Error(textValue(payload.message) || 'تعذر تسجيل المصروف.');
  }
  return {
    message: textValue(payload.message) || 'تم تسجيل المصروف.',
  };
}

export async function reverseOperationalExpenseInSupabase(
  expenseId: string,
  reason: string
): Promise<{ message: string }> {
  const { data, error } = await requireClient().rpc(
    'reverse_operational_expense',
    {
      p_expense_id: expenseId,
      p_reason: reason.trim(),
    }
  );
  if (error) throw new Error(error.message || 'تعذر عكس المصروف.');
  const payload = (data || {}) as RpcRecord;
  if (payload.success !== true) {
    throw new Error(textValue(payload.message) || 'تعذر عكس المصروف.');
  }
  return {
    message: textValue(payload.message) || 'تم عكس المصروف مع حفظ سجل المراجعة.',
  };
}

export async function closeCashShiftInSupabase(
  shiftId: string,
  actualCash: number,
  discrepancyReason?: string
): Promise<{ shift: Shift; message: string }> {
  const { data, error } = await requireClient().rpc('close_cash_shift', {
    p_shift_id: shiftId,
    p_actual_cash_in_minor_units: jodToMinorUnits(actualCash),
    p_discrepancy_reason: discrepancyReason?.trim() || null,
  });
  if (error) throw new Error(error.message || 'تعذر إغلاق الوردية.');
  const payload = (data || {}) as RpcRecord;
  if (payload.success !== true) {
    throw new Error(textValue(payload.message) || 'تعذر إغلاق الوردية.');
  }
  return {
    shift: mapShift(payload),
    message: textValue(payload.message) || 'تم إغلاق الوردية.',
  };
}

export async function cancelEmptyCashShiftInSupabase(
  shiftId: string,
  reason: string
): Promise<{ shift: Shift; message: string }> {
  const { data, error } = await requireClient().rpc('cancel_empty_cash_shift', {
    p_shift_id: shiftId,
    p_reason: reason.trim(),
  });
  if (error) throw new Error(error.message || 'تعذر إلغاء الوردية.');
  const payload = (data || {}) as RpcRecord;
  if (payload.success !== true) {
    throw new Error(textValue(payload.message) || 'تعذر إلغاء الوردية.');
  }
  return {
    shift: mapShift(payload),
    message:
      textValue(payload.message) ||
      'تم إلغاء الوردية الفارغة وحفظ السبب في سجل التدقيق.',
  };
}

src/services/supabase/orders.service.ts.beforeText:
import {safeGoogleMapsUrl, validMapCoordinates} from '../../utils/googleMaps';
import { supabase, isSupabaseConfigured } from '../../lib/supabase';
import { Order, OrderStatus, PaymentMethod, PaymentStatus } from '../../types';
import { isCustomerV2Order, runCustomerV2AdminAction } from './adminCustomerV2Lifecycle';
import { attachHistoricalParcelComposition } from './historicalParcelComposition';
import {storefrontReceiptUrl} from './pos.service';
import {
  calculateOrderAmountDue,
  type OperationalOrderFilter,
} from '../../utils/orderCalculations';

const paymentMethods: PaymentMethod[] = [
  'cash',
  'cash_on_delivery',
  'cliq',
  'card',
  'bank_transfer',
  'debt',
  'mixed',
];
const paymentStatuses: PaymentStatus[] = ['unpaid', 'partially_paid', 'paid', 'refunded'];

export type OperationalOrdersSort = 'newest' | 'oldest';

export interface OperationalOrdersPageInput {
  page: number;
  pageSize: number;
  filter: OperationalOrderFilter;
  searchQuery?: string;
  sort?: OperationalOrdersSort;
}

export interface OperationalOrdersSummary {
  review: number;
  active: number;
  due: number;
}

export interface OperationalOrdersPage {
  success: boolean;
  orders: OperationalOrderListItem[];
  page: number;
  pageSize: number;
  totalCount: number;
  totalPages: number;
  summary: OperationalOrdersSummary;
  error?: string;
}

export interface OperationalOrderListItem {
  id: string;
  orderNumber: string;
  customerName: string;
  customerPhone: string;
  governorate: string;
  region: string;
  status: OrderStatus;
  paymentMethod: PaymentMethod;
  paymentStatus: PaymentStatus;
  totalAmount: number;
  amountPaid: number;
  amountDue: number;
  itemCount: number;
  source?: string;
  /** Historical first line label from order_items.product_name_snapshot. */
  firstProductName: string;
  branchId: string;
  createdAt: string;
  updatedAt: string;
}

const EMPTY_OPERATIONAL_ORDERS_SUMMARY: OperationalOrdersSummary = {
  review: 0,
  active: 0,
  due: 0,
};

const ORDER_DETAIL_SELECT = `
  id,
  order_number,
  customer_id,
  customer_name_snapshot,
  status,
  payment_method,
  payment_status,
  payment_reference_number,
  payment_confirmed_at,
  payment_confirmed_by,
  cash_shift_id,
  subtotal_in_minor_units,
  delivery_fee_in_minor_units,
  delivery_zone,
  discount_in_minor_units,
  promotion_code_snapshot,
  total_in_minor_units,
  amount_paid_in_minor_units,
  customer_notes,
  internal_notes,
  whatsapp_message,
  tracking_token,
  public_receipt_token,
  delivery_started_at,
  estimated_arrival_at,
  delivery_completed_at,
  delivery_driver_phone,
  source,
  branch_id,
  warehouse_id,
  created_at,
  updated_at,
  customers (
    id,
    full_name,
    phone,
    email
  ),
  customer_addresses (
    id,
    governorate,
    city,
    area,
    street,
    building,
    floor,
    apartment,
    notes,
    latitude,
    longitude,
    formatted_address,
    google_maps_url,
    location_source,
    location_confirmed
  ),
  order_items (
    id,
    commercial_line_kind,
    base_unit_name_snapshot,
    product_id,
    product_name_snapshot,
    sku_snapshot,
    quantity,
    unit_price_in_minor_units,
    line_total_in_minor_units,
    sale_package_quantity,
    units_per_sale_package,
    sale_package_name_snapshot,
    sale_package_price_in_minor_units,
    products!order_items_product_id_fkey (
      id,
      cost_price_in_minor_units,
      base_unit:units!products_unit_id_fkey (
        name_ar
      ),
      product_images (
        image_url
      )
    )
  ),
  order_status_history (
    id,
    old_status,
    new_status,
    changed_by,
    notes,
    created_at
  ),
  sales_returns (
    id,
    return_number,
    reason,
    stock_disposition,
    refund_method,
    refund_amount_in_minor_units,
    reference_number,
    created_at
  )
`;

const OPERATIONAL_ORDER_LIST_SELECT = `
  id,
  order_number,
  customer_name_snapshot,
  status,
  payment_method,
  payment_status,
  total_in_minor_units,
  amount_paid_in_minor_units,
  source,
  branch_id,
  created_at,
  updated_at,
  customers (
    full_name,
    phone
  ),
  customer_addresses (
    governorate,
    city,
    area
  ),
  order_items (count)
`;

const OPERATIONAL_ORDER_ITEM_PREVIEW_SELECT = `
  id,
  order_id,
  product_name_snapshot,
  created_at
`;

const MAX_OPERATIONAL_ORDER_ITEMS = 50;

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value);

const asNonNegativeInteger = (value: unknown, fallback = 0): number => {
  const parsed = Number(value);
  return Number.isInteger(parsed) && parsed >= 0 ? parsed : fallback;
};

const asPositiveInteger = (value: number, fallback: number): number =>
  Number.isInteger(value) && value > 0 ? value : fallback;

function parseOperationalOrdersPagePayload(value: unknown): {
  orderIds: string[];
  totalCount: number;
  summary: OperationalOrdersSummary;
} | null {
  if (!isRecord(value) || !Array.isArray(value.order_ids)) return null;

  const summary = isRecord(value.summary) ? value.summary : {};
  return {
    orderIds: value.order_ids.filter(
      (orderId): orderId is string => typeof orderId === 'string'
    ),
    totalCount: asNonNegativeInteger(value.total_count),
    summary: {
      review: asNonNegativeInteger(summary.review_count),
      active: asNonNegativeInteger(summary.active_count),
      due: asNonNegativeInteger(summary.due_in_minor_units) / 1000,
    },
  };
}

function toPaymentMethod(value: unknown): PaymentMethod {
  return paymentMethods.includes(value as PaymentMethod)
    ? (value as PaymentMethod)
    : 'cash_on_delivery';
}

function toPaymentStatus(value: unknown): PaymentStatus {
  return paymentStatuses.includes(value as PaymentStatus)
    ? (value as PaymentStatus)
    : 'unpaid';
}

async function fetchOperationalOrderListRows(
  orderIds: readonly string[]
): Promise<{
  success: boolean;
  orders: OperationalOrderListItem[];
  error?: string;
}> {
  if (!isSupabaseConfigured || !supabase) {
    return {
      success: false,
      orders: [],
      error: 'لم يتم إعداد عميل Supabase بنجاح.',
    };
  }

  if (orderIds.length === 0) {
    return { success: true, orders: [] };
  }

  try {
    const previewLimit = orderIds.length * MAX_OPERATIONAL_ORDER_ITEMS;
    const [ordersResult, previewsResult] = await Promise.all([
      supabase
        .from('orders')
        .select(OPERATIONAL_ORDER_LIST_SELECT)
        .in('id', [...orderIds]),
      supabase
        .from('order_items')
        .select(OPERATIONAL_ORDER_ITEM_PREVIEW_SELECT)
        .in('order_id', [...orderIds])
        .order('order_id', { ascending: true })
        .order('created_at', { ascending: true })
        .order('id', { ascending: true })
        .limit(previewLimit),
    ]);

    const { data, error } = ordersResult;

    if (error) {
      console.error('[fetchOperationalOrderListRows Error]:', error);
      return { success: false, orders: [], error: error.message };
    }

    if (!data) {
      return { success: true, orders: [] };
    }

    if (previewsResult.error) {
      console.error(
        '[fetchOperationalOrderListRows Preview Error]:',
        previewsResult.error
      );
    }

    const firstProductNamesByOrderId = mapFirstProductNamesByOrderId(
      previewsResult.error ? [] : previewsResult.data
    );

    return {
      success: true,
      orders: mapOperationalOrderListRows(data, firstProductNamesByOrderId),
    };
  } catch (error) {
    console.error('[fetchOperationalOrderListRows Exception]:', error);
    return {
      success: false,
      orders: [],
      error:
        error instanceof Error
          ? error.message
          : 'حدث خطأ غير متوقع أثناء جلب صفحة الطلبات.',
    };
  }
}

function mapFirstProductNamesByOrderId(value: unknown): Map<string, string> {
  const firstProductNames = new Map<string, string>();
  if (!Array.isArray(value)) return firstProductNames;

  value.forEach((row) => {
    if (!isRecord(row)) return;
    const orderId = typeof row.order_id === 'string' ? row.order_id : '';
    const productName =
      typeof row.product_name_snapshot === 'string'
        ? row.product_name_snapshot.trim()
        : '';
    if (!orderId || !productName || firstProductNames.has(orderId)) return;
    firstProductNames.set(orderId, productName);
  });

  return firstProductNames;
}

function firstRelation(value: unknown): Record<string, unknown> {
  if (Array.isArray(value)) {
    return isRecord(value[0]) ? value[0] : {};
  }
  return isRecord(value) ? value : {};
}

function mapOperationalOrderListRows(
  data: unknown[],
  firstProductNamesByOrderId: ReadonlyMap<string, string> = new Map()
): OperationalOrderListItem[] {
  return data.flatMap((value) => {
    if (!isRecord(value) || typeof value.id !== 'string') return [];

    const customer = firstRelation(value.customers);
    const address = firstRelation(value.customer_addresses);
    const itemCountRelation = firstRelation(value.order_items);
    const totalAmount = Number(value.total_in_minor_units || 0) / 1000;
    const amountPaid = Number(value.amount_paid_in_minor_units || 0) / 1000;

    return [{
      id: value.id,
      orderNumber:
        typeof value.order_number === 'string' ? value.order_number : value.id,
      customerName:
        typeof customer.full_name === 'string'
          ? customer.full_name
          : typeof value.customer_name_snapshot === 'string'
            ? value.customer_name_snapshot
            : 'زبون نقدي',
      customerPhone:
        typeof customer.phone === 'string' ? customer.phone : '',
      governorate:
        typeof address.governorate === 'string'
          ? address.governorate
          : 'غير محدد',
      region:
        typeof address.area === 'string'
          ? address.area
          : typeof address.city === 'string'
            ? address.city
            : 'غير محدد',
      status:
        typeof value.status === 'string'
          ? (value.status as OrderStatus)
          : 'new',
      paymentMethod: toPaymentMethod(value.payment_method),
      paymentStatus: toPaymentStatus(value.payment_status),
      totalAmount,
      amountPaid,
      amountDue: calculateOrderAmountDue(totalAmount, amountPaid),
      itemCount: asNonNegativeInteger(itemCountRelation.count),
      firstProductName: firstProductNamesByOrderId.get(value.id) || '',
      source: typeof value.source === 'string' ? value.source : undefined,
      branchId: typeof value.branch_id === 'string' ? value.branch_id : '',
      createdAt:
        typeof value.created_at === 'string'
          ? value.created_at
          : new Date(0).toISOString(),
      updatedAt:
        typeof value.updated_at === 'string'
          ? value.updated_at
          : typeof value.created_at === 'string'
            ? value.created_at
            : new Date(0).toISOString(),
    }];
  });
}

function mapOrderRows(data: unknown[]): Order[] {
  return data.map((ord: any) => {
    const cust = ord.customers || {};
    const addr = ord.customer_addresses || {};

    const items = (ord.order_items || []).map((item: any) => {
      const prod = item.products || {};
      const unitPrice = Number(item.unit_price_in_minor_units || 0) / 1000;
      const lineTotal = Number(item.line_total_in_minor_units || 0) / 1000;
      const costPrice = Number(prod.cost_price_in_minor_units || 0) / 1000;
      const packageQuantity = Number(item.sale_package_quantity || 0);
      const unitsPerSalePackage = Number(item.units_per_sale_package || 0);
      const isWholesaleSnapshot = packageQuantity > 0 && unitsPerSalePackage > 0;
      const displayQuantity = isWholesaleSnapshot
        ? packageQuantity
        : Number(item.quantity || 1);
      const displayUnitPrice = isWholesaleSnapshot
        ? Number(item.sale_package_price_in_minor_units || 0) / 1000
        : unitPrice;

      const unitName = isWholesaleSnapshot
        ? item.sale_package_name_snapshot || 'طرد'
        : prod.base_unit?.name_ar || prod.unit || 'قطعة';
      const imgUrl =
        Array.isArray(prod.product_images) && prod.product_images.length > 0
          ? prod.product_images[0].image_url
          : prod.image_url || '';

      return {
        id: item.id,
        productId: item.product_id || '',
        productName: item.product_name_snapshot || 'منتج',
        productImage: imgUrl,
        sku: item.sku_snapshot || '',
        unit: unitName,
        unitPrice: displayUnitPrice,
        costPrice,
        quantity: displayQuantity,
        baseQuantity: Number(item.quantity || 1),
        unitsPerSalePackage: unitsPerSalePackage || undefined,
        salePackage: isWholesaleSnapshot ? unitName : undefined,
        discount: 0,
        totalPrice: lineTotal,
        commercialLineKind: item.commercial_line_kind || undefined,
        baseUnitName: item.base_unit_name_snapshot || undefined,
      };
    });

    const statusHistory = (ord.order_status_history || [])
      .map((h: any) => ({
        status: (h.new_status || 'new') as OrderStatus,
        changedAt: h.created_at || new Date().toISOString(),
        changedBy: h.changed_by || 'النظام',
        reason: h.notes || undefined,
      }))
      .sort(
        (a: any, b: any) =>
          new Date(b.changedAt).getTime() - new Date(a.changedAt).getTime()
      );

    const parsedLat = addr.latitude == null ? undefined : Number(addr.latitude);
    const parsedLng = addr.longitude == null ? undefined : Number(addr.longitude);
    const coordinatesValid = validMapCoordinates(parsedLat, parsedLng);
    const lat = coordinatesValid ? parsedLat : undefined;
    const lng = coordinatesValid ? parsedLng : undefined;
    const gMapsUrl = safeGoogleMapsUrl(addr.google_maps_url, lat, lng);

    const addressStr =
      addr.formatted_address ||
      [addr.governorate, addr.city, addr.area, addr.street, addr.building]
        .filter(Boolean)
        .join(' - ') ||
      'عنوان غير محدد';
    const totalAmount = Number(ord.total_in_minor_units || 0) / 1000;
    const amountPaid = Number(ord.amount_paid_in_minor_units || 0) / 1000;
    const salesReturn = Array.isArray(ord.sales_returns)
      ? ord.sales_returns[0]
      : ord.sales_returns;

    return {
      id: ord.id,
      orderNumber: ord.order_number,
      customerId: cust.id || ord.customer_id || undefined,
      customerName: cust.full_name || ord.customer_name_snapshot || 'زبون نقدي',
      customerPhone: cust.phone || '',
      governorate: addr.governorate || 'غير محدد',
      region: addr.area || addr.city || 'غير محدد',
      address: addressStr,
      customerAddress: {
        governorate: addr.governorate,
        area: addr.area,
        street: addr.street,
        building: addr.building,
        apartment: addr.apartment,
        landmark: addr.city,
        deliveryNotes: addr.notes,
      },
      latitude: lat,
      longitude: lng,
      formattedAddress: addr.formatted_address,
      googleMapsUrl: gMapsUrl,
      mapUrl: !gMapsUrl && typeof addr.google_maps_url === 'string' ? addr.google_maps_url : undefined,
      locationSource: addr.location_source || 'manual',
      locationConfirmed: Boolean(addr.location_confirmed),
      trackingToken: ord.tracking_token || undefined,
      publicReceiptUrl: ord.public_receipt_token?storefrontReceiptUrl(ord.public_receipt_token):undefined,
      deliveryStartedAt: ord.delivery_started_at || undefined,
      estimatedArrivalAt: ord.estimated_arrival_at || undefined,
      deliveryCompletedAt: ord.delivery_completed_at || undefined,
      deliveryDriverPhone: ord.delivery_driver_phone || undefined,
      items,
      subtotal: Number(ord.subtotal_in_minor_units || 0) / 1000,
      deliveryFee: Number(ord.delivery_fee_in_minor_units || 0) / 1000,
      deliveryZone:
        ord.delivery_zone === 'inside_ramtha' || ord.delivery_zone === 'outside_ramtha'
          ? ord.delivery_zone
          : undefined,
      discount: Number(ord.discount_in_minor_units || 0) / 1000,
      promotionCode: ord.promotion_code_snapshot || undefined,
      totalAmount,
      amountPaid,
      amountDue: calculateOrderAmountDue(totalAmount, amountPaid),
      paymentMethod: toPaymentMethod(ord.payment_method),
      paymentStatus: toPaymentStatus(ord.payment_status),
      paymentReferenceNumber: ord.payment_reference_number || undefined,
      paymentConfirmedAt: ord.payment_confirmed_at || undefined,
      paymentConfirmedBy: ord.payment_confirmed_by || undefined,
      cashShiftId: ord.cash_shift_id || undefined,
      returnNumber: salesReturn?.return_number || undefined,
      returnReason: salesReturn?.reason || undefined,
      returnStockDisposition: salesReturn?.stock_disposition || undefined,
      refundMethod: salesReturn?.refund_method || undefined,
      refundAmount: salesReturn
        ? Number(salesReturn.refund_amount_in_minor_units || 0) / 1000
        : undefined,
      refundReferenceNumber: salesReturn?.reference_number || undefined,
      returnedAt: salesReturn?.created_at || undefined,
      source: ord.source || 'website',
      status: (ord.status as OrderStatus) || 'new',
      branchId: ord.branch_id || '',
      isNew: ord.status === 'new',
      notes: ord.customer_notes,
      internalNotes: ord.internal_notes,
      createdAt: ord.created_at,
      updatedAt: ord.updated_at,
      statusHistory,
    };
  });
}

export async function fetchOrderByIdFromSupabase(
  orderId: string
): Promise<{ success: boolean; order?: Order; error?: string }> {
  if (!isSupabaseConfigured || !supabase) {
    return { success: false, error: 'عميل Supabase غير غير معد.' };
  }

  try {
    const { data, error } = await supabase
      .from('orders')
      .select(ORDER_DETAIL_SELECT)
      .eq('id', orderId)
      .single();

    if (error) {
      if (error.code === 'PGRST116') {
        return { success: false, error: 'الطلب غير موجود في قاعدة البيانات.' };
      }

      console.error('[fetchOrderByIdFromSupabase Error]:', error);
      return { success: false, error: error.message };
    }

    const [order] = mapOrderRows([data]);
    if (!order) {
      return { success: false, error: 'الطلب غير موجود في قاعدة البيانات.' };
    }

    const parcelItems = order.items.filter((item) => item.commercialLineKind === 'configurable_parcel');
    if (parcelItems.length > 0) {
      const instancesResult = await supabase.from('order_parcel_instances')
        .select('id,order_item_id,instance_sequence,units_per_parcel_snapshot,parcel_unit_name_snapshot')
        .eq('order_id', orderId).order('instance_sequence');
      if (instancesResult.error) throw instancesResult.error;
      const instances = instancesResult.data || [];
      const componentsResult = instances.length > 0
        ? await supabase.from('order_parcel_components')
          .select('id,parcel_instance_id,product_id,base_quantity,product_name_snapshot,sku_snapshot,base_unit_name_snapshot')
          .in('parcel_instance_id', instances.map((instance) => instance.id))
        : { data: [], error: null };
      if (componentsResult.error) throw componentsResult.error;
      attachHistoricalParcelComposition(order, instances, componentsResult.data || []);
    }
    return { success: true, order };
  } catch (err: any) {
    return { success: false, error: err?.message || 'تعذر جلب تفاصيل الطلب.' };
  }
}

export async function confirmOrderInSupabase(
  orderId: string,
  notes?: string
): Promise<{ success: boolean; message?: string; rawJson?: any; error?: string }> {
  if (!isSupabaseConfigured || !supabase) {
